import{_ as i,o as a,c as t,a2 as n}from"./chunks/framework.hwbV7reR.js";const o=JSON.parse('{"title":"Undercore Orchestrator","description":"","frontmatter":{},"headers":[],"relativePath":"quickstart.md","filePath":"quickstart.md","lastUpdated":1791444122000}'),e={name:"quickstart.md"};function h(p,s,l,k,r,F){return a(),t("div",null,[...s[0]||(s[0]=[n(`<h1 id="undercore-orchestrator" tabindex="-1">Undercore Orchestrator <a class="header-anchor" href="#undercore-orchestrator" aria-label="Permalink to &quot;Undercore Orchestrator&quot;">​</a></h1><p>Самостоятельный сервис управления VPN-узлами. Python 3.12+, SQLite, Linux/systemd. Оркестратор принимает запросы доверенного backend, управляет назначениями и возвращает конфигурацию. VPN-трафик идёт напрямую между приложением и VPN-узлом. Сайт Undercore не нужен для установки или управления.</p><h2 id="локальныи-запуск" tabindex="-1">Локальный запуск <a class="header-anchor" href="#локальныи-запуск" aria-label="Permalink to &quot;Локальный запуск&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> venv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .venv</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.venv/bin/python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> requirements.lock</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.venv/bin/python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-deps</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.venv/bin/undercore-orchestrator</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --directory</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PWD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/local&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.venv/bin/undercore-orchestrator</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --settings</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PWD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/local/settings.json&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.venv/bin/undercore-orchestrator</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --settings</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PWD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/local/settings.json&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span></span></code></pre></div><p><code>init</code> создаёт новый приватный каталог, ключ backend и настройки; повторный запуск не перезаписывает их. Добавьте <code>local/</code> в локальное исключение Git или используйте каталог вне checkout. Пустой реестр допустим: health процесса работает, но выдать подключение без сервера невозможно. Нельзя путать health процесса с проверкой VPN.</p><h2 id="добавление-сервера" tabindex="-1">Добавление сервера <a class="header-anchor" href="#добавление-сервера" aria-label="Permalink to &quot;Добавление сервера&quot;">​</a></h2><p>Нужен совместимый Amnezia-agent. Обычный сервер Amnezia без управляющего агента не подойдёт. <a href="./node-agent.html">Контракт агента</a> описывает обязательные операции и гарантии. TrustTunnel пока не реализован. Установка агента на VPS — отдельная операция.</p><p>Скопируйте <code>config/server.example.json</code> в приватный файл вне Git. Укажите HTTPS URL, закреплённый <code>server_id</code>, регион, ёмкость и путь к отдельному файлу ключа <code>api_key_file</code>. Оба файла должны иметь права 0600. Не вставляйте ключ в аргументы shell.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">undercore-orchestrator</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --settings</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/settings.json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /private/server.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">undercore-orchestrator</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --settings</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/settings.json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> servers</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">undercore-orchestrator</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --settings</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/settings.json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node-a</span></span></code></pre></div><p>Для редактирования используйте полный документ сервера с <code>expected_revision</code> из списка. Поле ключа можно опустить, сохранив текущий ключ:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">undercore-orchestrator</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node-a</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /private/change.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">undercore-orchestrator</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restore</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node-a</span></span></code></pre></div><p>Запускайте команды управления от пользователя службы <code>vpn-orchestrator</code>, например через <code>sudo -u vpn-orchestrator</code>. CLI работает локально с теми же сценариями, транзакциями и блокировками, что API. Сайт и административный HTTP API не нужны.</p><h2 id="установка-службы" tabindex="-1">Установка службы <a class="header-anchor" href="#установка-службы" aria-label="Permalink to &quot;Установка службы&quot;">​</a></h2><p>На чистом Linux нужны Python 3.12+, venv, pip и systemd. Скачайте проверенный релиз и SHA256SUMS. Скрипт <code>scripts/install.py</code> из доверенной версии репозитория проверяет архив, создаёт отдельного системного пользователя, каталоги и службы. Существующую установку он не перезаписывает:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/install.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/release.tar.gz</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --sha256</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> CHECKED_SHA256</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> undercore-orchestrator</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">undercore-orchestrator</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> undercore-orchestrator</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> undercore-orchestrator</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span></span></code></pre></div><p><code>start/stop/restart</code> доступны только на Linux/systemd. Остановка включает API, оба таймера и фоновые обработчики. Длительная остановка прекращает продление разрешений на узлах, поэтому управляемый VPN-доступ может остановиться. Установщик не открывает firewall, не выдаёт TLS-сертификат и не добавляет серверы. API слушает loopback: для удалённого backend настройте HTTPS reverse proxy и ограничение источников. Все маршруты требуют backend-токен; не передавайте его клиентам.</p><h2 id="обновление-и-резервная-копия" tabindex="-1">Обновление и резервная копия <a class="header-anchor" href="#обновление-и-резервная-копия" aria-label="Permalink to &quot;Обновление и резервная копия&quot;">​</a></h2><p>Существующий контролируемый <code>scripts/update.py</code> проверяет архив и миграцию на копии журнала, сохраняет backup и умеет вернуть код без восстановления устаревшей БД. Процедура описана в <a href="./operations.html">обслуживании</a>.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vpn-orchestrator</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> undercore-orchestrator</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backup</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /private/new-backup</span></span></code></pre></div><p>Копия включает консистентный SQLite snapshot, настройки, секреты узлов и backend, карту исходных путей. Это секретный архив-каталог, не диагностический экспорт. Не храните его в Git. Восстановление требует остановки всех writers, восстановления файлов по карте с правами 0600/0700 и сверки с агентами. Старый backup не отменяет выданный после него доступ на VPN-узлах; слепой откат запрещён.</p><h2 id="разработка" tabindex="-1">Разработка <a class="header-anchor" href="#разработка" aria-label="Permalink to &quot;Разработка&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.venv/bin/python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> requirements-dev.txt</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.venv/bin/python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pytest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -q</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.venv/bin/python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/check_contracts.py</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.venv/bin/ruff</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orchestrator</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.venv/bin/ruff</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> format</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orchestrator</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests</span></span></code></pre></div><p>Интеграционные тесты используют закреплённый агент с подменённым VPN backend; они не подключаются к серверам. <a href="./architecture.html">Архитектура</a>, <a href="./configuration.html">настройки</a>, <a href="./api.html">API</a>.</p>`,23)])])}const c=i(e,[["render",h]]);export{o as __pageData,c as default};
